import os
from typing import Any, Dict, List, Optional

import requests


def extract_invoice_fields(image_bytes: bytes) -> Dict[str, Any]:
    """
    Extract vendor, date, total, and line-item fields from an invoice using Google Document AI.
    Requires:
      - GOOGLE_CLOUD_PROJECT
      - GOOGLE_CLOUD_LOCATION (e.g. "us")
      - GOOGLE_DOCUMENT_AI_PROCESSOR_ID
      - GOOGLE_OAUTH_ACCESS_TOKEN
    """
    project_id = os.environ["GOOGLE_CLOUD_PROJECT"]
    location = os.environ.get("GOOGLE_CLOUD_LOCATION", "us")
    processor_id = os.environ["GOOGLE_DOCUMENT_AI_PROCESSOR_ID"]
    access_token = os.environ["GOOGLE_OAUTH_ACCESS_TOKEN"]

    url = (
        f"https://{location}-documentai.googleapis.com/v1/projects/"
        f"{project_id}/locations/{location}/processors/{processor_id}:process"
    )

    payload = {
        "rawDocument": {
            "mimeType": "image/png",
            "content": image_bytes.decode("latin1"),
        }
    }

    headers = {
        "Authorization": f"Bearer {access_token}",
        "Content-Type": "application/json",
    }

    resp = requests.post(url, json=payload, headers=headers, timeout=120)
    resp.raise_for_status()
    data = resp.json()

    document = data.get("document", {})
    entities = document.get("entities", [])

    def first_entity_of_type(entity_type: str) -> Optional[str]:
        for ent in entities:
            if ent.get("type_") == entity_type:
                return ent.get("mentionText") or ent.get("normalizedValue", {}).get("text")
        return None

    result = {
        "vendor": first_entity_of_type("supplier_name")
        or first_entity_of_type("vendor_name")
        or first_entity_of_type("receiver_name"),
        "date": first_entity_of_type("invoice_date")
        or first_entity_of_type("due_date")
        or first_entity_of_type("date"),
        "total": first_entity_of_type("total_amount")
        or first_entity_of_type("amount_due")
        or first_entity_of_type("grand_total"),
        "line_items": [],
    }

    for ent in entities:
        if ent.get("type_") in {"line_item", "line_item_group"}:
            line_item: Dict[str, Any] = {}
            props = ent.get("properties", []) or []
            for prop in props:
                ptype = prop.get("type_")
                text = prop.get("mentionText") or prop.get("normalizedValue", {}).get("text")
                if ptype in {"description", "product_code", "item"}:
                    line_item["description"] = text
                elif ptype in {"quantity", "qty"}:
                    line_item["quantity"] = text
                elif ptype in {"unit_price", "price"}:
                    line_item["unit_price"] = text
                elif ptype in {"amount", "line_amount", "total"}:
                    line_item["amount"] = text
            if line_item:
                result["line_items"].append(line_item)

    return result
